<template><section class="ops-card"><h2>{{ $t('Service teams') }}</h2><p class="ops-muted">{{ $t('Service teams organize responsibility only. Membership does not grant permissions or change referral rewards.') }}</p><div v-for="team in teams" :key="team.id" class="ops-record"><ops-fields :record="team"/><div class="ops-actions"><button @click="edit(team)">{{ $t('Edit') }}</button><Link :href="route('admin.operations.trace',{type:'team',reference:team.id})">{{ $t('Processing history') }} ↗</Link></div></div><form @submit.prevent="save" class="ops-form"><label>{{ $t('Team name') }}<input v-model.trim="form.name" maxlength="80" required></label><label>{{ $t('Member IDs') }}<input v-model.trim="members" placeholder="101,102" required></label><label>{{ $t('Status') }}<themed-select v-model="form.enabled"><option :value="true">{{ $t('Enabled') }}</option><option :value="false">{{ $t('Disabled') }}</option></themed-select></label><label class="ops-wide">{{ $t('Action and evidence') }}<textarea v-model.trim="form.reason" minlength="5" maxlength="2000" required/></label><div class="ops-actions"><button class="ops-primary" :disabled="busy">{{ $t(form.id?'Save':'Create team') }}</button><button type="button" @click="edit(null)">{{ $t('New team') }}</button></div></form></section></template>
<script>
import OpsFields from './Fields';export default {components:{OpsFields},props:{teams:Array},data(){return {busy:false,members:'',form:{id:null,revision:0,name:'',enabled:true,reason:'',request_key:crypto.randomUUID()}}},methods:{edit(team){this.form={id:team?team.id:null,revision:team?team.revision:0,name:team?team.name:'',enabled:team?team.enabled:true,reason:'',request_key:crypto.randomUUID()};this.members=team?team.member_ids.join(','):''},save(){this.$inertia.post(this.route('admin.operations.teams.update'),{...this.form,member_ids:this.members.split(/[,，\s]+/).filter(Boolean)},{preserveScroll:true,onStart:()=>this.busy=true,onSuccess:()=>this.edit(null),onFinish:()=>this.busy=false})}}};
</script>
